        }
        int[] result = new int[digits.length + 1];
        result[0] = 1;
        return result;
    }
}

class Solution {
    public int[] plusOne(int[] digits) {
        int n = digits.length;
        int carry = 1;
        for (int i = n - 1; i >= 0; i--) {
            int sum = digits[i] + carry;
            digits[i] = sum % 10;
            carry = sum / 10;
            if (carry == 0) {
                return digits;
            }
        }
        int[] result = new int[n + 1];
        result[0] = carry;
        for (int i = 0; i < n; i++) {
            result[i + 1] = digits[i];
        }
        return result;
    }
}

class Solution {
    public int[] plusOne(int[] digits) {
        int split = digits.length - 1;
        while (split >= 0 && digits[split] == 9) {
            split--;
        }

        if (split < 0) {
            int[] answer = new int[digits.length + 1];
            answer[0] = 1;
            return answer;
        }

        int[] answer = digits.clone();
        answer[split]++;
        for (int i = split + 1; i < answer.length; i++) {
            answer[i] = 0;
        }
        return answer;
    }
}

import java.util.Arrays;

class Solution {
    public int[] plusOne(int[] digits) {
        int n = digits.length;
        int[] answer = new int[n + 1];
        int carry = 1;
        for (int i = n - 1; i >= 0; i--) {
            int sum = digits[i] + carry;
            answer[i + 1] = sum % 10;
            carry = sum / 10;
        }
        answer[0] = carry;
        if (answer[0] == 0) {
            return Arrays.copyOfRange(answer, 1, answer.length);
        }
        return answer;
    }
}

class Solution {
    public int[] plusOne(int[] digits) {
        boolean overflow = addOne(digits, digits.length - 1);
        if (!overflow) {
            return digits;
        }
        int[] answer = new int[digits.length + 1];
        answer[0] = 1;
        return answer;
    }

    private boolean addOne(int[] digits, int index) {
        if (index < 0) {
            return true;
        }
        if (digits[index] < 9) {
            digits[index]++;
            return false;
        }
        digits[index] = 0;
        return addOne(digits, index - 1);
    }
}
